/* @autogenerated */
import {
  concat,
  defer,
  EMPTY,
  expand,
  map,
  Observable,
  of,
  switchMap,
  take,
  takeUntil,
  tap,
  throwError,
  timer,
} from 'rxjs';

export interface PollOptions<T> {
  /** Espera antes de la primera consulta (ms). */
  initial?: number;
  /** Espera máxima entre consultas (ms). */
  max?: number;
  /** Multiplicador de la espera tras cada consulta. */
  factor?: number;
  /** Tiempo total tras el que se abandona el sondeo (ms). */
  timeout?: number;
  /**
   * Valor a emitir cuando vence el timeout (recibe la última respuesta, si la hubo).
   * Si no se indica, el observable termina con PollTimeoutError.
   */
  onTimeout?: (last: T | undefined) => T;
}

export class PollTimeoutError extends Error {
  constructor(timeout: number) {
    super(`Polling timed out after ${timeout}ms`);
    this.name = 'PollTimeoutError';
  }
}

const DEFAULTS = { initial: 1000, max: 10_000, factor: 1.5, timeout: 5 * 60_000 };

/**
 * Consulta request$ con backoff exponencial hasta que isDone devuelva true
 * (emitiendo también esa última respuesta) o hasta que venza el timeout.
 */
export function pollUntil<T>(
  request$: Observable<T>,
  isDone: (value: T) => boolean,
  options: PollOptions<T> = {},
): Observable<T> {
  const { initial, max, factor, timeout } = { ...DEFAULTS, ...options };
  const delayFor = (attempt: number) => Math.min(initial * Math.pow(factor, attempt), max);

  return defer(() => {
    let last: T | undefined;
    let timedOut = false;

    const step = (attempt: number) =>
      timer(delayFor(attempt)).pipe(
        switchMap(() => request$.pipe(take(1))),
        map((value) => ({ value, attempt })),
      );

    const polling$ = step(0).pipe(
      expand(({ value, attempt }) => (isDone(value) ? EMPTY : step(attempt + 1))),
      map(({ value }) => value),
      tap((value) => (last = value)),
      takeUntil(timer(timeout).pipe(tap(() => (timedOut = true)))),
    );

    const onEnd$ = defer(() => {
      if (!timedOut) {
        return EMPTY;
      }
      return options.onTimeout ? of(options.onTimeout(last)) : throwError(() => new PollTimeoutError(timeout));
    });

    return concat(polling$, onEnd$);
  });
}
